/// <summary>
/// An <see cref="AIContextProvider"/> that gives agents the ability to maintain a persistent todo list
/// within a session.
/// </summary>
/// <remarks>
/// <para>
/// The provider exposes five function tools to the model during each invocation:
/// <list type="bullet">
/// <item><description><c>AddTodos</c> – add one or more items to the list.</description></item>
/// <item><description><c>CompleteTodos</c> – mark one or more items as complete.</description></item>
/// <item><description><c>RemoveTodos</c> – remove one or more items from the list.</description></item>
/// <item><description><c>GetRemainingTodos</c> – retrieve the items that are not yet complete.</description></item>
/// <item><description><c>GetAllTodos</c> – retrieve all items regardless of completion status.</description></item>
/// </list>
/// </para>
/// <para>
/// The todo list is stored per-session in the <see cref="AgentSession.StateBag"/> under the key <c>"TodoProvider"</c>,
/// so it persists across multiple invocations on the same session and can be serialized with the session.
/// </para>
/// </remarks>
public sealed class TodoProvider : AIContextProvider
{
    /// <summary>
    /// The key under which the todo state is stored in the <see cref="AgentSession.StateBag"/>.
    /// </summary>
    internal const string StateKey = "TodoProvider";

    private const string DefaultInstructions =
        "You have access to a persistent todo list for this session. " +
        "Use the AddTodos tool to record tasks that need to be done, CompleteTodos to mark tasks as finished, " +
        "RemoveTodos to delete tasks, GetRemainingTodos to review outstanding work, and GetAllTodos to review the full list. " +
        "Keep the todo list up to date as you make progress on multi-step tasks.";

    private readonly ProviderSessionState<TodoState> _sessionState;

    /// <summary>
    /// Initializes a new instance of the <see cref="TodoProvider"/> class.
    /// </summary>
    public TodoProvider()
    {
        this._sessionState = new ProviderSessionState<TodoState>(
            _ => new TodoState(),
            StateKey,
            AgentJsonUtilities.DefaultOptions);
    }

    /// <inheritdoc />
    protected override ValueTask<AIContext> ProvideAIContextAsync(InvokingContext context, CancellationToken cancellationToken = default)
    {
        var session = context.Session;

        var context_ = new AIContext
        {
            Instructions = DefaultInstructions,
            Tools =
            [
                AIFunctionFactory.Create(
                    (List<TodoItemInput> todos) => this.AddTodos(session, todos),
                    new AIFunctionFactoryOptions
                    {
                        Name = "AddTodos",
                        Description = "Add one or more items to the todo list. Each item receives an auto-incremented id.",
                        SerializerOptions = AgentJsonUtilities.DefaultOptions,
                    }),
                AIFunctionFactory.Create(
                    (List<int> ids) => this.CompleteTodos(session, ids),
                    new AIFunctionFactoryOptions
                    {
                        Name = "CompleteTodos",
                        Description = "Mark the todo items with the given ids as complete. Returns the number of items marked complete.",
                        SerializerOptions = AgentJsonUtilities.DefaultOptions,
                    }),
                AIFunctionFactory.Create(
                    (List<int> ids) => this.RemoveTodos(session, ids),
                    new AIFunctionFactoryOptions
                    {
                        Name = "RemoveTodos",
                        Description = "Remove the todo items with the given ids. Returns the number of items removed.",
                        SerializerOptions = AgentJsonUtilities.DefaultOptions,
                    }),
                AIFunctionFactory.Create(
                    () => this.GetRemainingTodos(session),
                    new AIFunctionFactoryOptions
                    {
                        Name = "GetRemainingTodos",
                        Description = "Get the todo items that have not yet been completed.",
                        SerializerOptions = AgentJsonUtilities.DefaultOptions,
                    }),
                AIFunctionFactory.Create(
                    () => this.GetAllTodosList(session),
                    new AIFunctionFactoryOptions
                    {
                        Name = "GetAllTodos",
                        Description = "Get all todo items, regardless of completion status.",
                        SerializerOptions = AgentJsonUtilities.DefaultOptions,
                    }),
            ],
        };

        return new ValueTask<AIContext>(context_);
    }

    /// <summary>
    /// Gets all todo items for the specified session.
    /// </summary>
    /// <param name="session">The session whose todo items should be retrieved.</param>
    /// <returns>A read-only list of all todo items. Returns an empty list for a session with no prior state.</returns>
    public IReadOnlyList<TodoItem> GetAllTodos(AgentSession? session)
        => this.GetAllTodosList(session);

    /// <summary>
    /// Gets the todo items for the specified session that have not yet been completed.
    /// </summary>
    /// <param name="session">The session whose todo items should be retrieved.</param>
    /// <returns>A list containing only the items where <see cref="TodoItem.IsComplete"/> is <see langword="false"/>.</returns>
    public List<TodoItem> GetRemainingTodos(AgentSession? session)
        => this._sessionState.GetOrInitializeState(session).Items.Where(item => !item.IsComplete).ToList();

    private List<TodoItem> GetAllTodosList(AgentSession? session)
        => this._sessionState.GetOrInitializeState(session).Items.ToList();

    private void AddTodos(AgentSession? session, List<TodoItemInput> todos)
    {
        var state = this._sessionState.GetOrInitializeState(session);

