                        SerializerOptions = AgentJsonUtilities.DefaultOptions,
                    }),
                AIFunctionFactory.Create(
                    (List<int> ids) => this.CompleteTodos(session, ids),
                    new AIFunctionFactoryOptions
                    {
                        Name = "CompleteTodos",
                        Description = "Mark the todo items with the given ids as complete. Returns the number of items marked complete.",
                        SerializerOptions = AgentJsonUtilities.DefaultOptions,
                    }),
                AIFunctionFactory.Create(
                    (List<int> ids) => this.RemoveTodos(session, ids),
                    new AIFunctionFactoryOptions
                    {
                        Name = "RemoveTodos",
                        Description = "Remove the todo items with the given ids. Returns the number of items removed.",
                        SerializerOptions = AgentJsonUtilities.DefaultOptions,
                    }),
                AIFunctionFactory.Create(
