    /// <summary>
    /// Gets all todo items for the specified session.
    /// </summary>
    /// <param name="session">The session whose todo items should be retrieved.</param>
    /// <returns>A read-only list of all todo items. Returns an empty list for a session with no prior state.</returns>
    public IReadOnlyList<TodoItem> GetAllTodos(AgentSession? session)
        => this.GetAllTodosList(session);

    /// <summary>
    /// Gets the todo items for the specified session that have not yet been completed.
    /// </summary>
    /// <param name="session">The session whose todo items should be retrieved.</param>
    /// <returns>A list containing only the items where <see cref="TodoItem.IsComplete"/> is <see langword="false"/>.</returns>
    public List<TodoItem> GetRemainingTodos(AgentSession? session)
        => this._sessionState.GetOrInitializeState(session).Items.Where(item => !item.IsComplete).ToList();

    private List<TodoItem> GetAllTodosList(AgentSession? session)
        => this._sessionState.GetOrInitializeState(session).Items.ToList();

    private void AddTodos(AgentSession? session, List<TodoItemInput> todos)
    {
        var state = this._sessionState.GetOrInitializeState(session);

        if (todos is not null)
        {
            foreach (var todo in todos)
            {
                state.Items.Add(new TodoItem
                {
                    Id = state.NextId++,
                    Title = todo?.Title ?? string.Empty,
                    Description = todo?.Description,
                    IsComplete = false,
                });
            }
        }

        this._sessionState.SaveState(session, state);
    }

    private int CompleteTodos(AgentSession? session, List<int> ids)
    {
        var state = this._sessionState.GetOrInitializeState(session);

        int count = 0;
        if (ids is not null)
        {
            var idSet = new HashSet<int>(ids);
            foreach (var item in state.Items)
            {
                if (idSet.Contains(item.Id))
                {
                    item.IsComplete = true;
                    count++;
                }
            }
        }

        this._sessionState.SaveState(session, state);
        return count;
    }

